      fullDesc: "سیلوار روزی آلدِرین بودند — دوم‌زادگان الهه‌ی آئلیث، که به سایه‌ها سپرده شدند تا نخست‌زادگان نور را نگه دارند. ده هزار سال در نقش جاسوس، قاتل، و رازدار خدمت کردند. آنگاه که شکاف آمد، سیلوار همان کاری را کردند که همیشه می‌کردند: زنده ماندند. به ژرفای جهان گریختند، آنجا که نور هرگز نمی‌رسد، و در آنجا شهرهایی از ابسیدین و استخوان ساختند. اما تاریکی بها می‌طلبد. سیلوار چیز دیگری شده‌اند. چشمانشان سازگار شده. پوستشان رنگ باخته. جان‌هایشان کم‌فروغ گشته. خورشید را به یاد نمی‌آورند. دلتنگش هم نیستند. فراموش کرده‌اند چه حسی داشت.",
