    "House Shadowmere": { name:"خاندان شَدمیر", seat:"اُندراث، تالار زیرین", motto:"در خاموش هم یک در وجود دارد.", desc:"درباری الفی در شبکه‌ای از غارها و راه‌های زیرزمینی. شدمیر چند گذرگاه امن را کنترل می‌کند و برای راهنما هزینه می‌گیرد؛ پنهان‌کاری‌اش میراث یورش‌ها و اختلاف‌های قدیمی است. مأمورانش در گردآوری خبر مهارت دارند، اما گزارش‌هایشان همیشه بی‌طرف نیست.", wealth:"زیاد؛ عوارض مسیر، قارچ‌های کمیاب و پیشه‌های تخصصی", military:"نیرومند در تونل‌ها؛ محدود در دشت باز" },
    "House Ironheart": { name:"خاندان آیرونهارت", seat:"هِرث‌فورج، دژ آهنین", motto:"سوگند باید وزن داشته باشد.", desc:"یکی از شوراهای اصلی دورف که حقوق آب، ایمنی تونل و دفاع چند دژ کوهستانی را برعهده دارد. نفوذش بر استانداردهای مهندسی و قراردادهایی استوار است که میان تالارهای رقیب پذیرفته شده‌اند. دورف‌ها یک پادشاه واحد ندارند و همه فرمان یک خاندان را نمی‌پذیرند.", wealth:"زیاد؛ معدن، مهندسی و قراردادهای راه", military:"نیرومند در دفاع کوهستانی و گذرگاه‌های دژبندی‌شده" },
