    "The Valerian Empire": { name:"امپراتوری والریان", seat:"والریوس‌رزت، شهر امپراتوری", motto:"یک قانون، بدهی‌های بسیار.", desc:"نیرومندترین دولت مرکزی انسانی، اما نه فرمانروای همهٔ انسان‌ها. دربارش قلب‌سرزمین را اداره می‌کند و پیمان‌های مرزی قدیمی را میراث امپراتوری می‌داند. امپراتور کنونی جاده، ادارهٔ مالیات و ارتش حرفه‌ای را بازسازی می‌کند، درحالی‌که زمین و مسیرهای بازرگانی هنوز در اختیار لردهای محلی است.", wealth:"بسیار زیاد؛ غله، گمرک، مالیات و تجارت رودخانه‌ای", military:"بزرگ‌ترین ارتش هماهنگ میان تاج‌های جنوب" },
    "House Vareth": { name:"خاندان وارث", seat:"منارهٔ خاکستر", motto:"گذرگاه را نگه دار؛ هزینه را بشمار.", desc:"خاندان مرزی‌ای که با دژها و انبارهای زمستانی چند راه شمالی را باز نگه می‌دارد. وارث دیده‌بان و سرباز فراهم می‌کند و در برابرش مالیات و اختیار گسترده می‌خواهد. رسماً به امپراتوری وفادار است، اما فرماندهانش بدون تضمین کنترل گذرگاه‌ها را واگذار نمی‌کنند.", wealth:"متوسط؛ عوارض، اجارهٔ زمین و قراردادهای نظامی", military:"نیروهای مرزی و دیده‌بانان باتجربه" },
    "House Stormborn": { name:"خاندان استورم‌بورن", seat:"دژ توفان، دماغهٔ توفان‌ها", motto:"هیچ بندری به‌تنهایی زنده نمی‌ماند.", desc:"خاندان ساحلی‌ای که از کشتی، راهنمای دریایی، نمک، شیلات و تعمیرگاه‌های بندری ثروت می‌گیرد. رقابتش با وارث بر سر گمرک، جاده و هزینهٔ نگهداری گذرگاه‌هاست؛ سروده‌های بعدی آن را به دشمنی ابدی بدل کرده‌اند. هر دو برای زنده‌ماندن به بندرهای مشترک نیاز دارند.", wealth:"زیاد؛ کشتیرانی، شیلات، نمک و عوارض بندری", military:"ناوگان نیرومند و میلیشیای ساحلی" },
