    "The Iron Fangs": { name:"نیش‌های آهنین", seat:"منارهٔ شکسته", motto:"زنده‌ها را بار می‌شمارند.", desc:"جنگاوری برده‌فروش که مسافران را می‌رباید و از طریق شبکه‌ای از دلالان می‌فروشد. رهبرانش پشت کاغذهای بدهی و خریداران دوردست پنهان می‌شوند؛ شکست نظامی به‌تنهایی کافی نیست و باید مقام‌ها، بازرگانان و کاروان‌دارانی را یافت که این تجارت را تأمین مالی می‌کنند.", wealth:"زیاد؛ تجارت غیرقانونی اسیران و باج‌گیری", military:"یورشگران متحرک و شبکهٔ خبرچینان" },
    "The Broken Skull": { name:"جمجمهٔ شکسته", seat:"شهر فروافتاده", motto:"هر روایت باید با سنگ روبه‌رو شود.", desc:"گروهی کوچک از اورک‌ها که سروده‌های کهن، قوانین قبیله‌ای و روایت‌های ناسازگار دربارهٔ کاروک را حفظ می‌کنند. برخی اعضا او را خدا می‌پرستند و برخی می‌گویند نام یک جنگ‌سالار بوده است. این فرقه به‌جای غارت تنها برای ثروت، اغلب برای دست‌نوشته‌ها یورش می‌برد؛ باورش وجود یک خدا را ثابت نمی‌کند.", wealth:"کم؛ دادوستد یادگار و پشتیبانی اردوگاه‌های پراکنده", military:"کوچک؛ متکی بر دیده‌بان و زمین‌شناسی محلی" },
    "The Adventurers' Guild": { name:"گیلد ماجراجویان", seat:"تالار بزرگ، حوضهٔ سیاه", motto:"با مدرک بازگرد.", desc:"نهادی چندنژادی که سفرهای اکتشافی را ثبت می‌کند، راه‌های خطرناک را مستند می‌سازد، هزینهٔ نجات را می‌پردازد و فقط آنچه اعضایش واقعاً دیده‌اند بایگانی می‌کند. شورای دوازده‌کرسی میان مناطق و پیشه‌ها توازن می‌سازد، اما در برابر حامیان ثروتمند آسیب‌پذیر است. تالار اصلی کنار هاویه است.", wealth:"زیاد؛ عضویت، قرارداد، غنیمت و نقشه‌برداری", military:"ارتش دائمی ندارد؛ اعضا برای هر مأموریت سازمان‌دهی می‌شوند" },
    "The Iron Pact": { name:"پیمان آهن", seat:"دژ آهنین، هِرث‌فورج", motto:"ابزار باید از سازنده‌اش بیشتر بپاید.", desc:"فدراسیونی از معدن‌کاران، آهنگران، مهندسان آسانسور و گروه‌های تعمیر. عضویت با شاگردی و گواهی مهارت به دست می‌آید، نه با تبار. این پیمان امن‌ترین راه‌های ژرف و بسیاری از تجهیزات کاوش را نگهداری می‌کند، اما انحصار همهٔ صنعت دورفی را در دست ندارد.", wealth:"زیاد؛ ابزار، قرارداد و نگهداری", military:"نگهبان و متخصص نجات محدود" }
